# then verify: changed cells == disagreement cells (where input != predicted), and unchanged elsewhere.
best = {}
for n in ['Demo pair %d'%i for i in range(1,7)] + ['Task test'] if False else ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4','Demo pair 5','Demo pair 6']:
    i=np.array(G[n+' input']); o=np.array(G[n+' output'])
    H,W=i.shape
    best_score = -1; bc=None
    for p_h in range(1,W+1):
