            for pr in range(p_v):
                for pc in range(p_h):
                    pred=np.zeros_like(i); ok=True
                    for r in range(H):
                        rr=(pr+r)%p_v
                        for c in range(W):
                            cc=(pc+c)%p_h
                            v=i[rr][cc]
