                    if score > best_score: best_score=score; bc=(p_h,p_v,pr,pc,err,ch.sum())
    print(n,'best:',bc, 'tiling_errors=',bc[0]+bc[1],'consistent_changed_only?', (bc[2],bc[3]) if False else 'pending')

