import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl',encoding='utf-8').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
T=G['Test input']
b1=T[2:6]; b2=T[14:18]
bests=None; maxo=-1
for s in range(28):
    o=0
    for i,(r1,r2) in enumerate(zip(b1,b2)):
        p={c+s for c,x in enumerate(r1) if x!=0}
        inter=len(p&{c for c,x in enumerate(r2) if x!=0})
        o+=inter
    if o>maxo: maxo=o; bests=s
print('best shift:',bests,'overlap:',maxo)
out=T.copy()
for i,(r1,r2) in enumerate(zip(b1,b2)):
    row=[0]*28
